fn chebweight(x: Vec<f32>) -> Vec<f32> {
    let n = x.len();
    let mut result = Vec::with_capacity(n);
    
    if n == 0 {
        return result; // Should not happen per problem statement, but handling edge case
    }
    
    for i in 0..n {
        if i == 0 || i == n - 1 {
            result.push(0.5);
        } else {
            result.push(1.0);
        }
    }
    
    result
}